const express=require('express');
const router=express.Router();
const {page}=require('../layout');
const {assets,employees}=require('../store');
const operations=require('../persistent-store');
const ewd=require('../ewd-store');
const rules=require('../ewd-rule-engine');
const {detachDriver}=require('../driver-assignment');

const DAY=86400000;
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const clean=s=>String(s??'').trim();
const n=v=>Number.isFinite(Number(v))?Number(v):null;
const ms=v=>{const x=new Date(v||0).getTime();return Number.isFinite(x)?x:0};
const employeeName=e=>[e?.firstName,e?.lastName].filter(Boolean).join(' ').trim()||e?.email||e?.id||'Driver';
const uid=e=>'SV365-'+String(e?.id||'UNKNOWN').replace(/[^A-Za-z0-9_-]/g,'').toUpperCase();
const nowIso=()=>new Date().toISOString();
const allowedOptions=['Standard','BFM'];

function prestartFor(asset){return asset?.driverPrestartId?operations.getPrestart(asset.driverPrestartId):null}
function prestartEligible(asset,employeeId){
  if(!asset||String(asset.currentDriverEmployeeId||'')!==String(employeeId||''))return null;
  const p=prestartFor(asset);if(!p||p.status!=='Passed'||!p.isPrimary)return null;
  if(Date.now()-ms(p.completedAt)>24*60*60*1000)return null;
  return p;
}
function eligibleAssignments(employeeId=''){
  return assets.filter(a=>a.currentDriverEmployeeId&&(!employeeId||String(a.currentDriverEmployeeId)===String(employeeId))).map(a=>{
    const emp=employees.find(e=>String(e.id)===String(a.currentDriverEmployeeId)),p=prestartEligible(a,a.currentDriverEmployeeId);
    if(!emp||!p)return null;
    return{assetId:a.id,assetName:a.name,rego:a.rego,assetType:a.type,odometer:Number(a.reading)||0,employeeId:emp.id,driverName:employeeName(emp),licenceNumber:emp.licenceNo||'',licenceState:emp.licenceState||'',prestartId:p.id,prestartCompletedAt:p.completedAt,prestartLocation:p.address||p.location||'',hasPin:ewd.hasPin(emp.id)};
  }).filter(Boolean);
}
function mustSession(id){const s=ewd.getSession(id);if(!s){const x=new Error('EWD session not found');x.status=404;throw x}return s}
function mustActive(id){const s=mustSession(id);if(s.status!=='ACTIVE'){const x=new Error('EWD session is not active');x.status=409;throw x}return s}
function lastEvent(s){return [...(s.events||[])].sort((a,b)=>ms(b.startTime)-ms(a.startTime))[0]||null}
function summary(s){
  const t=rules.tripTotals(s.events||[],s.startedAt,s.endedAt),gpsKm=rules.gpsDistanceKm(s.gps||[]),events=(s.events||[]).filter(x=>['Work','Rest'].includes(x.eventType));
  const firstOdo=events.find(x=>n(x.odometer)!=null)?.odometer,lastOdo=[...events].reverse().find(x=>n(x.odometer)!=null)?.odometer;
  const odoKm=n(firstOdo)!=null&&n(lastOdo)!=null&&Number(lastOdo)>=Number(firstOdo)?Math.round(Number(lastOdo)-Number(firstOdo)):null;
  return{...t,distanceKm:odoKm??gpsKm,gpsDistanceKm:gpsKm,odometerDistanceKm:odoKm,breaks:events.filter(x=>x.eventType==='Rest').length,workChanges:events.filter(x=>x.eventType==='Work').length,alerts:(s.alerts||[]).length,potentialNonCompliance:rules.analyse(s.events||[],s.workRestOption,s.endedAt||nowIso()).potentialNonCompliance.length,gpsPoints:(s.gps||[]).length};
}
function enriched(s){return{...s,fatigue:rules.analyse(s.events||[],s.workRestOption,s.endedAt||nowIso()),summary:summary(s)}}
function checkPin(employeeId,pin,allowCreate=false){
  if(!ewd.hasPin(employeeId)){if(!allowCreate){const x=new Error('Create your EWD PIN before continuing');x.status=401;throw x}ewd.setPin(employeeId,pin);return true}
  if(!ewd.verifyPin(employeeId,pin)){const x=new Error('Incorrect EWD PIN');x.status=401;throw x}return true;
}
function locationFrom(b={}){return{latitude:n(b.latitude),longitude:n(b.longitude),name:clean(b.locationName)||clean(b.location)||((n(b.latitude)!=null&&n(b.longitude)!=null)?`${Number(b.latitude).toFixed(5)}, ${Number(b.longitude).toFixed(5)}`:'Location not supplied')}}
function createEvent(s,b,type){
  const stamp=clean(b.timestamp)||nowIso(),start=clean(b.startTime)||stamp,odo=n(b.odometer);
  if(odo==null||odo<0){const x=new Error('Odometer is required for each work/rest change');x.status=400;throw x}
  return{id:'EWDE-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase(),clientEventId:clean(b.clientEventId)||'',eventType:type,historicData:!!b.historicData,location:locationFrom(b),odometer:Math.round(odo),registration:s.rego,startTime:start,timestamp:stamp,comment:clean(b.comment),origin:b.origin||'EWD',createdAt:stamp,modifiedAt:null,confirmedAt:null,correctionLog:[]};
}
function syncAlerts(s){
  const a=rules.analyse(s.events||[],s.workRestOption),next=a.nextLimit;
  if(a.activity!=='Work'||!next||['ok','info'].includes(next.severity))return a;
  const last=lastEvent(s),key=[next.ruleId,next.severity,last?.id||'none'].join(':');
  ewd.addAlert(s.id,{id:'EWDA-'+Date.now().toString(36).toUpperCase(),dedupeKey:key,timestamp:nowIso(),severity:next.severity,ruleId:next.ruleId,title:next.remainingWorkMin<=0?'Potential non-compliance':'Fatigue break approaching',message:a.message});
  return a;
}
function driverHistory(employeeId){const since=Date.now()-28*DAY;return ewd.sessionsForDriver(employeeId,since)}
function exportShape(s){
  return{technologyProviderId:'Supervisor365 Candidate - NOT NHVR APPROVED',driverInfo:{driverId:s.driverId,driverLicenceIssued:s.licenceState||'OTH',driverLicenceNumber:s.licenceNumber||'',driverName:s.driverName},numberPlateEvents:[{newNumberPlate:s.rego,timestamp:s.startedAt}],twoUpEvents:s.twoUpEvents||[],workRestEvents:(s.events||[]).filter(x=>['Work','Rest'].includes(x.eventType)).map(x=>({eventType:x.eventType,historicData:!!x.historicData,location:x.location,odometer:x.odometer,startTime:x.startTime,timestamp:x.timestamp})),workRestOptionEvents:[{workRestOption:s.workRestOption,timestamp:s.startedAt}],comments:(s.events||[]).filter(x=>x.comment).map(x=>({comment:x.comment,timestamp:x.timestamp})),authorisedOfficerAnnotations:s.annotations||[]};
}

router.get('/api/ewd/bootstrap',(req,res)=>{
  const employeeId=clean(req.query.employeeId),eligible=eligibleAssignments(employeeId),active=employeeId?ewd.getActiveSession(employeeId):null;
  res.set('Cache-Control','no-store');
  res.json({candidate:true,approvalStatus:'NOT_NHVR_APPROVED',eligible,active:active?enriched(active):null,history:employeeId?driverHistory(employeeId).slice(-10).reverse().map(s=>({id:s.id,startedAt:s.startedAt,endedAt:s.endedAt,status:s.status,rego:s.rego,driverName:s.driverName,summary:summary(s)})):[]});
});
router.get('/api/ewd/session/:id',(req,res)=>{try{const s=mustSession(req.params.id);if(s.status==='ACTIVE')syncAlerts(s);res.set('Cache-Control','no-store');res.json(enriched(mustSession(req.params.id)))}catch(e){res.status(e.status||500).json({error:e.message})}});
router.get('/api/ewd/session/:id/export',(req,res)=>{try{const s=mustSession(req.params.id);res.set('Content-Disposition',`attachment; filename="${s.id}-ewd.json"`);res.json(exportShape(s))}catch(e){res.status(e.status||500).json({error:e.message})}});

router.post('/api/ewd/start',(req,res)=>{
  try{
    const b=req.body||{},employeeId=clean(b.employeeId),assetId=clean(b.assetId),emp=employees.find(e=>String(e.id)===employeeId),asset=assets.find(a=>String(a.id)===assetId);
    if(!emp||!asset)return res.status(404).json({error:'Driver or vehicle not found'});
    const p=prestartEligible(asset,employeeId);if(!p)return res.status(409).json({error:'EWD can only start after a current Passed primary pre-start for this driver and vehicle.',code:'PRESTART_REQUIRED'});
    if(ewd.getActiveSession(employeeId))return res.status(409).json({error:'This driver already has an active EWD session'});
    const assetBusy=ewd.listSessions().find(s=>s.status==='ACTIVE'&&String(s.assetId)===assetId);if(assetBusy)return res.status(409).json({error:'This vehicle already has an active EWD session'});
    const option=clean(b.workRestOption)||'Standard';if(!allowedOptions.includes(option))return res.status(400).json({error:'This candidate build currently enables Standard and BFM reference profiles only. AFM/other options require an approved rule set configuration.'});
    checkPin(employeeId,b.pin,!!b.createPin);
    const stamp=clean(b.timestamp)||nowIso(),id='EWD-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase();
    const s={id,status:'ACTIVE',approvalStatus:'CANDIDATE_NOT_APPROVED',employeeId:emp.id,driverId:uid(emp),driverName:employeeName(emp),licenceNumber:emp.licenceNo||'',licenceState:emp.licenceState||'OTH',assetId:asset.id,assetName:asset.name,assetType:asset.type,rego:asset.rego,prestartId:p.id,prestartCompletedAt:p.completedAt,driverBase:clean(b.driverBase),baseTimeZone:clean(b.baseTimeZone)||'Australia/Brisbane',baseUtcOffset:clean(b.baseUtcOffset)||'+10:00',recordKeeperLocation:clean(b.recordKeeperLocation),workRestOption:option,accreditationNumber:clean(b.accreditationNumber),drivingArrangement:'Solo',startedAt:clean(b.startTime)||stamp,endedAt:null,endReason:'',events:[],gps:[],alerts:[],confirmations:[],annotations:[],twoUpEvents:[],createdAt:stamp,updatedAt:stamp,system:{approvalHolder:'Supervisor365 Candidate',name:'Supervisor365 EWD Candidate',version:'0.1.0',approvalStatus:'NOT_NHVR_APPROVED'}};
    const ev=createEvent(s,{...b,startTime:s.startedAt,timestamp:stamp,comment:clean(b.comment)||`EWD started after pre-start ${p.id}`},'Work');s.events.push(ev);ewd.saveSession(s);asset.reading=ev.odometer;syncAlerts(s);
    res.status(201).json(enriched(mustSession(id)));
  }catch(e){res.status(e.status||500).json({error:e.message||'Unable to start EWD'})}
});
router.post('/api/ewd/session/:id/gps',(req,res)=>{try{const s=mustActive(req.params.id),b=req.body||{};const point={clientEventId:clean(b.clientEventId)||'',timestamp:clean(b.timestamp)||nowIso(),latitude:n(b.latitude),longitude:n(b.longitude),accuracy:n(b.accuracy),speed:n(b.speed),heading:n(b.heading)};if(point.latitude==null||point.longitude==null)return res.status(400).json({error:'Valid GPS coordinates required'});ewd.addGps(s.id,point);res.json({ok:true})}catch(e){res.status(e.status||500).json({error:e.message})}});
router.post('/api/ewd/session/:id/change',(req,res)=>{
  try{
    let s=mustActive(req.params.id);const b=req.body||{},type=clean(b.eventType);if(!['Work','Rest'].includes(type))return res.status(400).json({error:'Activity must be Work or Rest'});
    const current=lastEvent(s);if(current?.eventType===type)return res.status(409).json({error:`Driver is already in ${type}`});
    const ev=createEvent(s,b,type);if(ms(ev.startTime)<ms(s.startedAt)||ms(ev.startTime)>Date.now()+60000)return res.status(400).json({error:'Work/rest change time is outside the active EWD period'});
    ewd.addEvent(s.id,ev);const asset=assets.find(a=>String(a.id)===String(s.assetId));if(asset)asset.reading=ev.odometer;s=mustSession(s.id);syncAlerts(s);res.status(201).json(enriched(mustSession(s.id)));
  }catch(e){res.status(e.status||500).json({error:e.message})}
});
router.post('/api/ewd/session/:id/comment',(req,res)=>{try{const s=mustActive(req.params.id),text=clean(req.body?.comment);if(!text)return res.status(400).json({error:'Comment is required'});ewd.updateSession(s.id,x=>{x.driverComments=Array.isArray(x.driverComments)?x.driverComments:[];x.driverComments.push({id:'EWDC-'+Date.now().toString(36).toUpperCase(),comment:text,timestamp:clean(req.body?.timestamp)||nowIso(),location:locationFrom(req.body||{})})});res.json(enriched(mustSession(s.id)))}catch(e){res.status(e.status||500).json({error:e.message})}});
router.post('/api/ewd/session/:id/manual-entry',(req,res)=>{
  try{
    const s=mustActive(req.params.id),b=req.body||{},type=clean(b.eventType);if(!['Work','Rest'].includes(type))return res.status(400).json({error:'Activity must be Work or Rest'});if(!clean(b.comment))return res.status(400).json({error:'A reason/comment is required for a missed entry'});
    const ev=createEvent(s,{...b,historicData:false,origin:'EWD'},type),confirmed=(s.confirmations||[]).some(c=>ms(c.confirmedThrough)>=ms(ev.startTime));if(confirmed)return res.status(409).json({error:'This time period has already been confirmed and cannot be amended'});if(ms(ev.startTime)<ms(s.startedAt)||ms(ev.startTime)>Date.now())return res.status(400).json({error:'Missed entry must fall within the current EWD period'});
    ewd.updateSession(s.id,x=>{x.events=x.events||[];if(x.events.some(e=>Math.abs(ms(e.startTime)-ms(ev.startTime))<60000))throw Object.assign(new Error('An activity change already exists at that time'),{status:409});x.events.push(ev);x.events.sort((a,b)=>ms(a.startTime)-ms(b.startTime))});syncAlerts(mustSession(s.id));res.status(201).json(enriched(mustSession(s.id)));
  }catch(e){res.status(e.status||500).json({error:e.message})}
});
router.post('/api/ewd/session/:id/correct',(req,res)=>{
  try{
    const s=mustActive(req.params.id),b=req.body||{},eventId=clean(b.eventId),reason=clean(b.reason);if(!reason)return res.status(400).json({error:'A correction comment is required'});const ev=(s.events||[]).find(x=>String(x.id)===eventId);if(!ev)return res.status(404).json({error:'Work/rest entry not found'});if(ev.confirmedAt)return res.status(409).json({error:'Confirmed EWD entries cannot be corrected'});if(ev.historicData)return res.status(409).json({error:'Historic entries cannot be corrected'});
    ewd.updateSession(s.id,x=>{const row=x.events.find(y=>String(y.id)===eventId),before={startTime:row.startTime,location:row.location,odometer:row.odometer,comment:row.comment};row.correctionLog=Array.isArray(row.correctionLog)?row.correctionLog:[];row.correctionLog.push({timestamp:nowIso(),reason,before});if(b.startTime)row.startTime=clean(b.startTime);if(b.locationName||b.latitude!=null||b.longitude!=null)row.location=locationFrom(b);if(n(b.odometer)!=null)row.odometer=Math.round(n(b.odometer));row.comment=[row.comment,`Correction: ${reason}`].filter(Boolean).join(' · ');row.modifiedAt=nowIso();x.events.sort((a,b)=>ms(a.startTime)-ms(b.startTime))});syncAlerts(mustSession(s.id));res.json(enriched(mustSession(s.id)));
  }catch(e){res.status(e.status||500).json({error:e.message})}
});
router.post('/api/ewd/session/:id/confirm',(req,res)=>{
  try{
    const s=mustSession(req.params.id);checkPin(s.employeeId,req.body?.pin,false);if(req.body?.accepted!==true)return res.status(400).json({error:'Driver declaration must be accepted'});const stamp=clean(req.body?.timestamp)||nowIso();ewd.updateSession(s.id,x=>{for(const ev of x.events||[])if(!ev.confirmedAt&&ms(ev.startTime)<=ms(stamp))ev.confirmedAt=stamp;x.confirmations=x.confirmations||[];x.confirmations.push({timestamp:stamp,confirmedThrough:stamp,driverId:x.driverId,driverName:x.driverName,declarationVersion:'Schedule A',reAuthenticated:true})});res.json(enriched(mustSession(s.id)));
  }catch(e){res.status(e.status||500).json({error:e.message})}
});
router.post('/api/ewd/session/:id/end',(req,res)=>{
  try{
    let s=mustActive(req.params.id),b=req.body||{};if(b.changeToRest&&lastEvent(s)?.eventType!=='Rest'){const ev=createEvent(s,{...b,eventType:'Rest',comment:clean(b.comment)||'End of trip - rest commenced'},'Rest');ewd.addEvent(s.id,ev);s=mustSession(s.id)}
    if(b.confirmDay){checkPin(s.employeeId,b.pin,false);if(b.accepted!==true)return res.status(400).json({error:'Driver declaration must be accepted before confirming the day'});const stamp=clean(b.timestamp)||nowIso();ewd.updateSession(s.id,x=>{for(const ev of x.events||[])if(!ev.confirmedAt)ev.confirmedAt=stamp;x.confirmations=x.confirmations||[];x.confirmations.push({timestamp:stamp,confirmedThrough:stamp,driverId:x.driverId,driverName:x.driverName,declarationVersion:'Schedule A',reAuthenticated:true})})}
    const endStamp=clean(b.timestamp)||nowIso();ewd.updateSession(s.id,x=>{x.status='ENDED';x.endedAt=endStamp;x.endReason=clean(b.endReason)||'Trip completed'});const asset=assets.find(a=>String(a.id)===String(s.assetId));if(asset&&String(asset.currentDriverEmployeeId||'')===String(s.employeeId)){try{detachDriver(asset,{reason:'ewd_trip_ended',detachedAt:endStamp,expectedEmployeeId:s.employeeId})}catch{}}
    res.json(enriched(mustSession(s.id)));
  }catch(e){res.status(e.status||500).json({error:e.message})}
});
router.post('/api/ewd/session/:id/annotation',(req,res)=>{try{const s=mustSession(req.params.id),b=req.body||{},annotation=clean(b.annotation);if(!annotation)return res.status(400).json({error:'Annotation is required'});ewd.addAnnotation(s.id,{id:'EWDAO-'+Date.now().toString(36).toUpperCase(),flaggedTime:clean(b.flaggedTime)||nowIso(),interceptTime:clean(b.interceptTime)||nowIso(),location:locationFrom(b),annotation,timestamp:nowIso(),officerName:clean(b.officerName)});res.status(201).json({ok:true,session:enriched(mustSession(s.id))})}catch(e){res.status(e.status||500).json({error:e.message})}});

function eventRows(s){return[...(s.events||[])].sort((a,b)=>ms(b.startTime)-ms(a.startTime)).map(e=>`<tr><td><b>${esc(e.eventType)}</b></td><td>${new Date(e.startTime).toLocaleString('en-AU')}</td><td>${esc(e.location?.name||'—')}</td><td>${Number(e.odometer||0).toLocaleString('en-AU')}</td><td>${esc(s.workRestOption)}</td><td>${esc(e.comment||'—')}</td><td>${esc(e.origin||'EWD')}</td><td>${new Date(e.timestamp).toLocaleString('en-AU')}</td></tr>`).join('')||'<tr><td colspan="8">No entries.</td></tr>'}
function graphFor(s){
  const date=new Date(s.startedAt),dayStart=new Date(date.getFullYear(),date.getMonth(),date.getDate()).getTime(),dayEnd=dayStart+DAY,events=[...(s.events||[])].filter(x=>ms(x.startTime)<dayEnd).sort((a,b)=>ms(a.startTime)-ms(b.startTime));let segs='';
  for(let i=0;i<events.length;i++){const e=events[i],start=Math.max(dayStart,ms(e.startTime)),end=Math.min(dayEnd,i+1<events.length?ms(events[i+1].startTime):ms(s.endedAt||nowIso()));if(end<=start)continue;const left=(start-dayStart)/DAY*100,width=(end-start)/DAY*100;segs+=`<div class="gseg ${e.eventType.toLowerCase()}" style="left:${left}%;width:${Math.max(.3,width)}%" title="${esc(e.eventType)} ${new Date(start).toLocaleTimeString('en-AU')}"></div>`}
  return`<div class="graphHours">${[0,3,6,9,12,15,18,21,24].map(h=>`<span style="left:${h/24*100}%">${String(h).padStart(2,'0')}</span>`).join('')}</div><div class="graphRow"><b>WORK</b><div class="graphTrack workTrack">${segs}</div></div><div class="graphRow"><b>REST</b><div class="graphTrack restTrack">${segs}</div></div>`;
}

router.get('/ewd/compliance/:id',(req,res)=>{
  try{const s=mustSession(req.params.id),a=rules.analyse(s.events||[],s.workRestOption,s.endedAt||nowIso()),annotations=(s.annotations||[]).map(x=>`<tr><td>${esc(x.flaggedTime)}</td><td>${esc(x.interceptTime)}</td><td>${esc(x.location?.name||'')}</td><td>${esc(x.annotation)}</td></tr>`).join('')||'<tr><td colspan="4">No authorised officer annotations.</td></tr>',non=a.potentialNonCompliance.map(x=>`<tr><td>${esc(x.time)}</td><td>${esc(x.workRestOption)}</td><td>${esc(x.period)}</td><td>${esc(x.activity)}</td><td><b>${esc(x.level)}</b></td></tr>`).join('')||'<tr><td colspan="5">No calculated potential non-compliance in this candidate session.</td></tr>';
    res.send(page('ewd','EWD Compliance View',`<style>.cv{max-width:1500px;margin:auto}.cvHead{background:#0b1724;color:#fff;border-radius:16px;padding:18px 20px;margin-bottom:14px;display:flex;justify-content:space-between;gap:15px}.cvWarn{color:#ffcf72;font-size:11px}.cvGrid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-bottom:14px}.cvCard,.cvPanel{background:#fff;border:1px solid #dfe6ed;border-radius:12px;padding:13px}.cvCard span{font-size:9px;color:#7b8999;text-transform:uppercase;font-weight:850}.cvCard b{display:block;margin-top:5px}.graph{padding:25px 12px 14px}.graphHours{position:relative;height:18px;margin-left:62px}.graphHours span{position:absolute;font-size:8px;color:#8390a0;transform:translateX(-50%)}.graphRow{display:grid;grid-template-columns:52px 1fr;gap:10px;align-items:center;margin:9px 0}.graphRow>b{font-size:9px}.graphTrack{height:24px;background:#edf1f5;border-radius:6px;position:relative;overflow:hidden}.gseg{position:absolute;height:100%;top:0}.workTrack .gseg.work{background:#2385d5}.workTrack .gseg.rest{display:none}.restTrack .gseg.rest{background:#2aa56a}.restTrack .gseg.work{display:none}.cvPanel{padding:0;overflow:hidden}.cvPanel h2{padding:14px 15px;margin:0;border-bottom:1px solid #e6ebf0;font-size:14px}.annotate{padding:14px;display:grid;grid-template-columns:1fr 1fr;gap:8px}.annotate .full{grid-column:1/-1}@media(max-width:800px){.cvGrid{grid-template-columns:1fr 1fr}.cvHead{flex-direction:column}.annotate{grid-template-columns:1fr}.annotate .full{grid-column:auto}}</style><div class="cv"><div class="cvHead"><div><div style="font-size:10px;color:#58d1f2;font-weight:900;text-transform:uppercase">Compliance View</div><h1 style="margin:5px 0">${esc(s.driverName)} · ${esc(s.rego)}</h1><div class="cvWarn">CANDIDATE SYSTEM - NOT NHVR APPROVED</div></div><div><a class="secondary" href="/ewd?employee=${encodeURIComponent(s.employeeId)}">Return to Driver View</a></div></div><div class="cvGrid"><div class="cvCard"><span>Driver Licence</span><b>${esc(s.licenceNumber||'—')}</b></div><div class="cvCard"><span>Work Option</span><b>${esc(s.workRestOption)}</b></div><div class="cvCard"><span>Driver Base / TZ</span><b>${esc(s.driverBase||'—')} · ${esc(s.baseUtcOffset||'')}</b></div><div class="cvCard"><span>EWD System</span><b>Supervisor365 Candidate v0.1.0</b></div></div><section class="cvPanel"><h2>24-hour Graphical Summary</h2><div class="graph">${graphFor(s)}</div></section><section class="cvPanel" style="margin-top:12px"><h2>Work & Rest Changes</h2><div class="tablewrap"><table><thead><tr><th>Activity</th><th>Time</th><th>Location</th><th>Odometer</th><th>Option</th><th>Comments</th><th>Origin</th><th>Entry Timestamp</th></tr></thead><tbody>${eventRows(s)}</tbody></table></div></section><section class="cvPanel" style="margin-top:12px"><h2>Investigation Aid - Potential Non-compliance</h2><div class="tablewrap"><table><thead><tr><th>Time</th><th>Option</th><th>Period</th><th>Work / Rest</th><th>Level</th></tr></thead><tbody>${non}</tbody></table></div></section><section class="cvPanel" style="margin-top:12px"><h2>Authorised Officer Annotations</h2><div class="tablewrap"><table><thead><tr><th>Flag Time</th><th>Intercept Time</th><th>Location</th><th>Annotation</th></tr></thead><tbody id="annotationRows">${annotations}</tbody></table></div><form class="annotate" id="officerForm"><input id="officerName" placeholder="Officer name / identifier"><input id="officerLocation" placeholder="Intercept location"><input class="full" id="officerAnnotation" placeholder="Annotation" required><button class="primary full" type="submit">Commit Annotation</button></form></section><div style="margin-top:12px;display:flex;gap:8px;justify-content:flex-end"><a class="secondary" href="/api/ewd/session/${encodeURIComponent(s.id)}/export">Export Schedule A JSON</a></div></div><script>(()=>{const f=document.getElementById('officerForm');f.onsubmit=async e=>{e.preventDefault();const body={officerName:document.getElementById('officerName').value,locationName:document.getElementById('officerLocation').value,annotation:document.getElementById('officerAnnotation').value};const r=await fetch('/api/ewd/session/${encodeURIComponent(s.id)}/annotation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),j=await r.json();if(!r.ok)return alert(j.error||'Unable to save annotation');location.reload()}})();</script>`));
  }catch(e){res.status(e.status||500).send(page('ewd','EWD Compliance View',`<div class="panel" style="padding:20px">${esc(e.message)}</div>`))}
});

router.get('/ewd/summary/:id',(req,res)=>{try{const s=mustSession(req.params.id),sum=summary(s);res.send(page('ewd','EWD Trip Summary',`<style>.sum{max-width:900px;margin:auto}.sumHero{padding:22px;border-radius:18px;background:linear-gradient(135deg,#0a1725,#123a50);color:#fff}.sumGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0}.sumCard{background:#fff;border:1px solid #e1e7ed;border-radius:12px;padding:15px}.sumCard span{font-size:9px;text-transform:uppercase;color:#8491a1;font-weight:850}.sumCard b{display:block;font-size:22px;margin-top:6px}@media(max-width:650px){.sumGrid{grid-template-columns:1fr 1fr}}</style><div class="sum"><div class="sumHero"><div style="font-size:9px;color:#5dd8f5;font-weight:900;text-transform:uppercase">Trip Summary</div><h1>${esc(s.rego)} · ${esc(s.driverName)}</h1><div>${new Date(s.startedAt).toLocaleString('en-AU')} → ${s.endedAt?new Date(s.endedAt).toLocaleString('en-AU'):'Active'}</div></div><div class="sumGrid"><div class="sumCard"><span>Total Work</span><b>${esc(sum.workLabel)}</b></div><div class="sumCard"><span>Total Rest</span><b>${esc(sum.restLabel)}</b></div><div class="sumCard"><span>Distance</span><b>${sum.distanceKm??0} km</b></div><div class="sumCard"><span>Breaks</span><b>${sum.breaks}</b></div><div class="sumCard"><span>GPS Points</span><b>${sum.gpsPoints}</b></div><div class="sumCard"><span>Potential Issues</span><b>${sum.potentialNonCompliance}</b></div></div><section class="panel"><div class="tablewrap"><table><thead><tr><th>Activity</th><th>Time</th><th>Location</th><th>Odometer</th><th>Option</th><th>Comments</th><th>Origin</th><th>Entry Timestamp</th></tr></thead><tbody>${eventRows(s)}</tbody></table></div></section><div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px"><a class="secondary" href="/ewd/compliance/${encodeURIComponent(s.id)}">Compliance View</a><a class="primary" href="/ewd?employee=${encodeURIComponent(s.employeeId)}">Back to EWD</a></div></div>`))}catch(e){res.status(e.status||500).send(page('ewd','EWD Trip Summary',esc(e.message)))}});

